describe('ConversationTimer', () => {
    beforeEach(() => {
        vi.useFakeTimers()
        vi.setSystemTime(new Date('2026-01-01T00:00:05.000Z'))
    })

    afterEach(() => {
        cleanup()
        vi.useRealTimers()
    })

    it('freezes at the completed duration when the run is done', () => {
        render(
            <ConversationTimer
                completedAt="2026-01-01T00:01:30.000Z"
                startedAt="2026-01-01T00:00:00.000Z"
                status="completed"
            />,
        )

        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('1:30')

        act(() => {
            vi.advanceTimersByTime(3_000)
        })

        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('1:30')
    })

    it('ticks once a second while the run is active', () => {
        render(<ConversationTimer completedAt={null} startedAt="2026-01-01T00:00:00.000Z" status="running" />)

        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:05')

        act(() => {
            vi.advanceTimersByTime(3_000)
        })

        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:08')
    })

    it.each(['idle', 'waitingForInput', 'completed', 'failed', 'cancelled'] as const)(
        'does not tick while status is %s',
        (status) => {
            render(<ConversationTimer completedAt={null} startedAt="2026-01-01T00:00:00.000Z" status={status} />)

            expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:05')

            act(() => {
                vi.advanceTimersByTime(3_000)
            })

            expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:05')
        },
    )

    it('resets elapsed duration when the displayed conversation changes', () => {
        const { rerender } = render(
            <ConversationTimer completedAt={null} startedAt="2026-01-01T00:00:00.000Z" status="idle" />,
        )
        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:05')

        rerender(<ConversationTimer completedAt={null} startedAt="2026-01-01T00:00:04.000Z" status="idle" />)

        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:01')
    })

    it('resumes from the frozen value without counting time spent waiting', () => {
        const { rerender } = render(
            <ConversationTimer completedAt={null} startedAt="2026-01-01T00:00:00.000Z" status="running" />,
        )

        act(() => {
            vi.advanceTimersByTime(3_000)
        })
        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:08')

        rerender(<ConversationTimer completedAt={null} startedAt="2026-01-01T00:00:00.000Z" status="waitingForInput" />)
        act(() => {
            vi.advanceTimersByTime(10_000)
        })
        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:08')

        rerender(<ConversationTimer completedAt={null} startedAt="2026-01-01T00:00:00.000Z" status="running" />)
        act(() => {
            vi.advanceTimersByTime(2_000)
        })

        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:10')
    })
})

import { Typography } from '@mui/material'
import { useEffect, useRef, useState } from 'react'
import type { PopupRunStatus } from '../run/popup/action_popup_defaults'
import { formatDuration } from './conversation_duration'

interface ConversationTimerProps {
    completedAt: string | null
    startedAt: string
    status: PopupRunStatus
}

function elapsedMs(startedAt: string, completedAt: string | null) {
    const end = completedAt ? Date.parse(completedAt) : Date.now()

    return end - Date.parse(startedAt)
}

/**
 * Isolated run timer. While the run is active it ticks once a second; keeping it
 * in its own component means only this node re-renders, not the whole chat log.
 */
export function ConversationTimer({ completedAt, startedAt, status }: ConversationTimerProps) {
    const [timerState, setTimerState] = useState(() => ({ elapsed: elapsedMs(startedAt, null), startedAt }))
    const lastTickAtRef = useRef(0)
    if (timerState.startedAt !== startedAt) {
        setTimerState({ elapsed: elapsedMs(startedAt, null), startedAt })
    }

    useEffect(() => {
        if (completedAt || status !== 'running') return

        lastTickAtRef.current = Date.now()
        const interval = setInterval(() => {
            const now = Date.now()
            const elapsedSinceLastTick = now - lastTickAtRef.current
            lastTickAtRef.current = now
            setTimerState((currentState) => ({
                ...currentState,
                elapsed: currentState.elapsed + elapsedSinceLastTick,
            }))
        }, 1000)

        return () => clearInterval(interval)
    }, [completedAt, status])

    const displayedElapsed = completedAt ? elapsedMs(startedAt, completedAt) : timerState.elapsed

    return (
        <Typography aria-label="Elapsed time" color="text.secondary" variant="caption">
            {`â± ${formatDuration(displayedElapsed)}`}
        </Typography>
    )
}

const { sumAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');

function createMessageEntry(id, role, content, timestamp, agent, sequence) {
    return {
        ...(agent ? { agent } : {}),
        content,
        id,
        kind: 'message',
        role,
        ...(Number.isSafeInteger(sequence) ? { sequence } : {}),
        timestamp,
    };
}

function createEventEntry(id, type, content, timestamp, sequence) {
    return {
        content,
        id,
        kind: 'event',
        ...(Number.isSafeInteger(sequence) ? { sequence } : {}),
        timestamp,
        type,
    };
}

function createProviderEventEntry(providerEvent, id, timestamp, sequence) {
    const event = {
        content: providerEvent.content,
        id,
        kind: 'event',
        label: providerEvent.label,
        providerItemId: providerEvent.providerItemId,
        sequence,
        status: providerEvent.status,
        timestamp,
        type: providerEvent.type,
    };
    if (typeof providerEvent.command === 'string') event.command = providerEvent.command;
    if (Number.isSafeInteger(providerEvent.deletions) && providerEvent.deletions >= 0) event.deletions = providerEvent.deletions;
    if (Array.isArray(providerEvent.details)) event.details = [...providerEvent.details];
    if (Number.isFinite(providerEvent.durationMs)) event.durationMs = providerEvent.durationMs;
    if (Number.isSafeInteger(providerEvent.exitCode)) event.exitCode = providerEvent.exitCode;
    if (Number.isSafeInteger(providerEvent.insertions) && providerEvent.insertions >= 0) event.insertions = providerEvent.insertions;
    if (typeof providerEvent.output === 'string') event.output = providerEvent.output;
    if (Array.isArray(providerEvent.summary)) event.summary = [...providerEvent.summary];
    if (typeof providerEvent.workingDirectory === 'string') event.workingDirectory = providerEvent.workingDirectory;

    return event;
}

function accumulateUsage(current, turn) {
    return sumAgentTokenUsage([current, turn]);
}

function createConversation(request, id, startedAt, reference) {
    if (request.conversation) {
        return {
            ...request.conversation,
            completedAt: null,
            entries: [...request.conversation.entries],
            path: reference,
            providerSessions: [...request.conversation.providerSessions],
            status: 'running',
        };
    }

    return {
        actionId: request.actionId ?? null,
        cardInternalId: request.activityOrigin.kind === 'card' ? request.activityOrigin.cardInternalId : null,
        cardPath: request.cardPath ?? null,
        completedAt: null,
        entries: [],
        hasExplicitTitle: true,
        id,
        path: reference,
        providerSessions: [],
        startedAt,
        status: 'running',
        title: typeof request.title === 'string' && request.title.length > 0 ? request.title : 'Agent run',
        viewed: true,
    };
}

/** Snapshots the mutable conversation collections while reusing immutable entries. */
function snapshotConversation(conversation) {
    return {
        ...conversation,
        entries: [...conversation.entries],
        providerSessions: [...conversation.providerSessions],
    };
}

function updateProviderSession(run, synchronizedThroughMessageId, completedAt) {
    const conversationId = run.providerConversationId ?? run.request.providerConversationId;
    if (!conversationId) return;

    const sessions = run.conversation.providerSessions;
    const current = sessions.find(({ agent }) => agent === run.agent);
    const nextSession = {
        agent: run.agent,
        conversationId,
        createdAt: current?.createdAt ?? completedAt,
        lastUsedAt: completedAt,
        synchronizedThroughMessageId,
    };
    run.conversation.providerSessions = current
        ? sessions.map((session) => (session.agent === run.agent ? nextSession : session))
        : [...sessions, nextSession];
}

module.exports = {
    accumulateUsage,
    createProviderEventEntry,
    createConversation,
    createEventEntry,
    createMessageEntry,
    snapshotConversation,
    updateProviderSession,
};

