const { buildResumeAgentCommand, resolveAgentCommand } = require('../agent/agent_profiles.mjs');
const { normalizeConversationContext } = require('../agent/agent_transcript');
const { resolveAgentPrompt, resolvePlaceholders } = require('./action_text');

const CONTINUE_INPUT = 'continue';
function continuationReferencePath(reference) {
    return reference;
}

function withoutProviderConversationId(request) {
    return Object.fromEntries(Object.entries(request).filter(([fieldName]) => fieldName !== 'providerConversationId'));
}

function withoutConversation(result) {
    return Object.fromEntries(Object.entries(result).filter(([fieldName]) => fieldName !== 'conversation'));
}

function executionCommand(resolvedAgent, providerSession, streaming) {
    if (!providerSession) return resolvedAgent.command;
    if (!streaming || resolvedAgent.agent === 'claude') {
        return buildResumeAgentCommand(resolvedAgent.profile, providerSession.conversationId, resolvedAgent.command);
    }

    return resolvedAgent.command;
}

class ActionAgentExecutor {
    constructor(dependencies) {
        this.agentConfigProvider = dependencies.agentConfigProvider;
        this.agentRunnerService = dependencies.agentRunnerService;
        this.localGitService = dependencies.localGitService;
    }

    async execute(input) {
        const config = this.agentConfigProvider();
        const permissionMode = input.runInput.permissionMode ?? input.action.permissionMode;
        const thinkingLevel = input.runInput.thinkingLevel ?? input.action.thinkingLevel;
        const streaming = input.action.streaming;
        const resolvedAgent = resolveAgentCommand(config, {
            ...(input.runInput.agent ? { agent: input.runInput.agent } : (input.action.agent ? { agent: input.action.agent } : {})),
            ...(input.runInput.model ? { model: input.runInput.model } : (input.action.model ? { model: input.action.model } : {})),
            ...(permissionMode ? { permissionMode } : {}),
            ...(thinkingLevel ? { thinkingLevel } : {}),
        }, streaming);
        const sourceConversation = input.runInput.continueFrom
            ? await this.localGitService.loadAgentConversation(
                input.primaryProject,
                continuationReferencePath(input.runInput.continueFrom),
            )
            : null;
        const expectedCardInternalId = input.activityOrigin.kind === 'card' ? input.activityOrigin.cardInternalId : null;
        if (sourceConversation && sourceConversation.cardInternalId !== expectedCardInternalId) {
            throw new Error(`Agent conversation belongs to ${sourceConversation.cardInternalId}, not ${expectedCardInternalId}`);
        }

        const providerSession = sourceConversation?.providerSessions
            ?.find(({ agent }) => agent === resolvedAgent.agent) ?? null;
        const hasPromptOverride = Object.hasOwn(input.runInput, 'prompt');
        const prompt = hasPromptOverride
            ? resolvePlaceholders(
                input.runInput.prompt,
                input.context,
                input.project,
                input.primaryProject,
                input.projectFolder,
                input.releasesFolder,
                input.activeCardsFolder,
                input.runInput.extraPrompt,
            )
            : sourceConversation
                ? input.runInput.extraPrompt.trim().length > 0 ? input.runInput.extraPrompt : CONTINUE_INPUT
                : resolveAgentPrompt(
                    input.action,
                    input.context,
                    input.project,
                    input.primaryProject,
                    input.projectFolder,
                    input.releasesFolder,
                    input.activeCardsFolder,
                    input.runInput.extraPrompt,
                );
        const command = executionCommand(resolvedAgent, providerSession, streaming);
        const contextInput = sourceConversation
            ? normalizeConversationContext(sourceConversation, providerSession?.synchronizedThroughMessageId ?? null)
            : '';
        const reference = input.runInput.continueFrom
            ? continuationReferencePath(input.runInput.continueFrom)
            : input.conversationReservation?.reference;
        const request = {
            actionId: input.action.id,
            agent: resolvedAgent.agent,
            activityOrigin: input.activityOrigin,
            activityProject: input.primaryProject,
            ...(input.context.file ? { cardPath: input.context.file } : {}),
            command,
            ...(sourceConversation ? { conversation: sourceConversation, reference } : {}),
            ...(!sourceConversation && input.conversationReservation
                ? { conversationId: input.conversationReservation.conversationId, reference }
                : {}),
            ...(contextInput ? { contextInput } : {}),
            actionRunId: input.runId,
            prompt,
            projectFolder: input.projectFolder,
            streaming,
            ...(providerSession ? { providerConversationId: providerSession.conversationId } : {}),
            title: input.action.label,
        };
        const fallback = {
            command: resolvedAgent.command,
            contextInput: sourceConversation ? normalizeConversationContext(sourceConversation) : '',
        };
        const result = await this.runAgentTurn(input, request, fallback);
        const executionResult = withoutConversation(result);

        return {
            ...executionResult,
            agent: resolvedAgent.agent,
            model: resolvedAgent.model,
            permissionMode: resolvedAgent.permissionMode,
            thinkingLevel: resolvedAgent.thinkingLevel,
        };
    }

    async runAgentTurn(input, request, fallback) {
        const result = await this.runAgentProcess(input, request);
        if (!request.providerConversationId || !result.missingSession || result.turnStarted) return result;

        const fallbackRequest = {
            ...withoutProviderConversationId(request),
            command: fallback.command,
            conversation: result.conversation,
            ...(fallback.contextInput ? { contextInput: fallback.contextInput } : {}),
            reference: result.reference,
            reuseLastUserMessage: true,
        };

        return this.runAgentProcess(input, fallbackRequest);
    }

    async runAgentProcess(input, request) {
        const { promise, reject, resolve } = Promise.withResolvers();
        const onComplete = (exitCode, run) => resolve({
            command: request.command,
            changedPaths: run.changedPaths ? [...run.changedPaths] : [],
            conversation: run.conversation,
            conversationId: run.conversation.id,
            exitCode,
            missingSession: run.missingSession,
            prompt: request.prompt,
            reference: run.reference,
            stderr: run.stderr,
            stdout: run.stdout,
            queuedMessage: run.queuedMessage?.content ?? null,
            turnStarted: run.turnStarted,
        });
        const onEvent = (agentEvent) => input.onEvent(agentEvent);
        const started = await this.agentRunnerService.start(input.project, request, onEvent, onComplete, reject);
        input.onActiveRunChange(started.runId);

        try {
            if (input.signal.aborted) this.agentRunnerService.stop(started.runId);

            return await promise;
        } finally {
            input.onActiveRunChange(null);
        }
    }
}

module.exports = { ActionAgentExecutor, continuationReferencePath };

import { normalizeAgentTokenUsage } from './agent_usage_math.mjs'

const AGENT_MESSAGE_ROLES = new Set(['assistant', 'user'])
const AGENT_STATUSES = new Set(['cancelled', 'completed', 'failed', 'running', 'waitingForInput'])
const INTERNAL_EVENT_TYPES = new Set(['closed', 'started', 'turnCompleted'])

function requiredString(value, fieldName) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Malformed agent conversation: missing ${fieldName}`)

    return value
}

function optionalString(value) {
    return typeof value === 'string' && value.length > 0 ? value : null
}

function optionalInteger(value) {
    return Number.isSafeInteger(value) ? value : null
}

function optionalNonNegativeInteger(value) {
    return Number.isSafeInteger(value) && value >= 0 ? value : null
}

function optionalNumber(value) {
    return typeof value === 'number' && Number.isFinite(value) ? value : null
}

function optionalStringArray(value) {
    return Array.isArray(value) && value.every((entry) => typeof entry === 'string') ? [...value] : null
}

function normalizeMessage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    if (!AGENT_MESSAGE_ROLES.has(value.role)) return null
    if (typeof value.content !== 'string') return null
    const id = optionalString(value.id)
    const timestamp = optionalString(value.timestamp)
    if (!id || !timestamp) return null
    const agent = optionalString(value.agent)
    const sequence = optionalInteger(value.sequence)

    return {
        ...(agent ? { agent } : {}),
        content: value.content,
        id,
        kind: 'message',
        role: value.role,
        ...(sequence !== null ? { sequence } : {}),
        timestamp,
    }
}

function normalizeEvent(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    if (typeof value.content !== 'string') return null
    const id = optionalString(value.id)
    const timestamp = optionalString(value.timestamp)
    const type = optionalString(value.type)
    if (!id || !timestamp || !type) return null
    const command = optionalString(value.command)
    const deletions = optionalNonNegativeInteger(value.deletions)
    const details = optionalStringArray(value.details)
    const durationMs = optionalNumber(value.durationMs)
    const exitCode = optionalInteger(value.exitCode)
    const insertions = optionalNonNegativeInteger(value.insertions)
    const label = optionalString(value.label)
    const output = value.type !== 'commandExecution' && typeof value.output === 'string' ? value.output : null
    const providerItemId = optionalString(value.providerItemId)
    const sequence = optionalInteger(value.sequence)
    const status = optionalString(value.status)
    const summary = optionalStringArray(value.summary)
    const workingDirectory = optionalString(value.workingDirectory)

    return {
        ...(command ? { command } : {}),
        content: value.content,
        ...(deletions !== null ? { deletions } : {}),
        ...(details ? { details } : {}),
        ...(durationMs !== null ? { durationMs } : {}),
        ...(exitCode !== null ? { exitCode } : {}),
        id,
        ...(insertions !== null ? { insertions } : {}),
        kind: 'event',
        ...(label ? { label } : {}),
        ...(output !== null ? { output } : {}),
        ...(providerItemId ? { providerItemId } : {}),
        ...(sequence !== null ? { sequence } : {}),
        ...(status ? { status } : {}),
        ...(summary ? { summary } : {}),
        timestamp,
        type,
        ...(workingDirectory ? { workingDirectory } : {}),
    }
}

function normalizeProviderSession(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    const agent = optionalString(value.agent)
    const conversationId = optionalString(value.conversationId)
    const createdAt = optionalString(value.createdAt)
    const lastUsedAt = optionalString(value.lastUsedAt)
    const synchronizedThroughMessageId = optionalString(value.synchronizedThroughMessageId)
    if (!agent || !conversationId || !createdAt || !lastUsedAt || !synchronizedThroughMessageId) return null

    return { agent, conversationId, createdAt, lastUsedAt, synchronizedThroughMessageId }
}

function normalizeContextWindowUsage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    const { capacityTokens, usedTokens } = value
    if (!Number.isSafeInteger(usedTokens) || usedTokens < 0) return null
    if (!Number.isSafeInteger(capacityTokens) || capacityTokens <= 0) return null

    return { capacityTokens, usedTokens }
}

function normalizeArray(value, normalize) {
    if (!Array.isArray(value)) return []

    return value.map(normalize).filter((entry) => entry !== null)
}

function coalesceDiagnosticEntries(entries) {
    const groupedEntries = []
    for (const entry of entries) {
        const previousEntry = groupedEntries.at(-1)
        if (entry.kind === 'event' && entry.type === 'diagnostic'
            && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            groupedEntries[groupedEntries.length - 1] = {
                ...previousEntry,
                content: `${previousEntry.content}\n${entry.content}`,
            }
            continue
        }
        groupedEntries.push(entry)
    }

    return groupedEntries
}

function isConversationEntry(entry) {
    if (entry.kind !== 'event') return true
    if (INTERNAL_EVENT_TYPES.has(entry.type)) return false

    return entry.type !== 'error' || typeof entry.providerItemId === 'string'
}

function normalizeEntries(value) {
    if (!Array.isArray(value)) throw new Error('Malformed agent conversation: missing entries')

    const entries = value.map((entry, index) => {
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
            throw new Error(`Malformed agent conversation: invalid entries[${index}]`)
        }
        const normalized = entry.kind === 'message'
            ? normalizeMessage(entry)
            : entry.kind === 'event'
                ? normalizeEvent(entry)
                : null
        if (!normalized) throw new Error(`Malformed agent conversation: invalid entries[${index}]`)

        return normalized
    })

    return coalesceDiagnosticEntries(entries.filter(isConversationEntry))
}

/** Parse one canonical conversation record and validate every ordered entry. */
export function parseAgentConversation(content, referencePath) {
    const parsed = JSON.parse(content)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Malformed agent conversation: root must be an object')
    const id = requiredString(parsed.id, 'id')
    const status = requiredString(parsed.status, 'status')
    if (!AGENT_STATUSES.has(status)) throw new Error(`Malformed agent conversation: invalid status ${status}`)
    const startedAt = requiredString(parsed.startedAt, 'startedAt')
    const hasExplicitTitle = typeof parsed.title === 'string' && parsed.title.trim().length > 0
    const contextWindowUsage = normalizeContextWindowUsage(parsed.contextWindowUsage)
    const usage = normalizeAgentTokenUsage(parsed.usage)
    if (parsed.viewed !== undefined && typeof parsed.viewed !== 'boolean') {
        throw new Error('Malformed agent conversation: invalid viewed')
    }

    return {
        actionId: optionalString(parsed.actionId),
        cardInternalId: optionalString(parsed.cardInternalId),
        cardPath: optionalString(parsed.cardPath),
        completedAt: optionalString(parsed.completedAt),
        ...(contextWindowUsage ? { contextWindowUsage } : {}),
        entries: normalizeEntries(parsed.entries),
        hasExplicitTitle,
        id,
        path: referencePath,
        providerSessions: normalizeArray(parsed.providerSessions, normalizeProviderSession),
        startedAt,
        status,
        title: hasExplicitTitle ? parsed.title : id,
        ...(usage ? { usage } : {}),
        viewed: parsed.viewed ?? true,
    }
}

import type { ActionContext } from '../../../data/action_context'
import type { AgentConversation } from '../../../data/data_types'
import { actionPromptDraftService } from '../../../services/actions/action_prompt_draft_service'
import { actionRunRegistry } from '../../../services/actions/action_run_registry'
import { dialogService } from '../../../services/dialog_service'
import type { ConversationPickerConversation } from './action_conversation_picker_data'
import { defaultLoadConversation, defaultLoadConversations } from '../run/popup/action_popup_defaults'

interface ActionConversationSnapshot {
    conversations: AgentConversation[]
    loading: boolean
    selectedConversation: AgentConversation | null
}

type Listener = () => void

function belongsToContext(conversation: ConversationPickerConversation, context: ActionContext) {
    return context.kind === 'project'
        ? conversation.cardInternalId === null
        : conversation.cardInternalId === context.cardInternalId
}

function conversationTimestamp(conversation: ConversationPickerConversation) {
    const timestamp = Date.parse(conversation.startedAt)

    return Number.isNaN(timestamp) ? 0 : timestamp
}

export function conversationOptions<T extends ConversationPickerConversation>(
    conversations: T[],
    actionId: string,
    context: ActionContext,
    liveConversation: T | null,
) {
    const byId = new Map<string, T>()
    for (const conversation of conversations) {
        if (belongsToContext(conversation, context) && conversation.actionId === actionId) {
            byId.set(conversation.id, conversation)
        }
    }
    if (liveConversation && belongsToContext(liveConversation, context) && liveConversation.actionId === actionId) {
        byId.set(liveConversation.id, liveConversation)
    }

    return [...byId.values()].sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))
}

function latestWaitingConversation(conversations: AgentConversation[], actionId: string, context: ActionContext) {
    return conversations
        .filter((conversation) => belongsToContext(conversation, context)
            && conversation.actionId === actionId
            && conversation.status === 'waitingForInput')
        .sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))[0] ?? null
}

/** Owns history loading and selection for one popup action/context binding. */
export class ActionConversationStore {
    private readonly actionId: string
    private readonly context: ActionContext
    private initialSelectionConfigured = false
    private initialSelectionPath: string | null = null
    private loadRequest = 0
    private readonly listeners = new Set<Listener>()
    private snapshot: ActionConversationSnapshot = { conversations: [], loading: true, selectedConversation: null }

    constructor(actionId: string, context: ActionContext) {
        this.actionId = actionId
        this.context = context
    }

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: Listener) => {
        this.listeners.add(listener)

        return () => this.listeners.delete(listener)
    }

    /** Sets one automatic selection consumed by initial history load. */
    configureInitialSelection(path: string | null) {
        if (this.initialSelectionConfigured) return

        this.initialSelectionConfigured = true
        this.initialSelectionPath = path
    }

    async load() {
        const request = this.loadRequest + 1
        this.loadRequest = request
        this.setSnapshot({ ...this.snapshot, loading: true })
        try {
            const conversations = await defaultLoadConversations(this.context)
            if (request !== this.loadRequest) return

            const run = actionRunRegistry.getActionRunStore(this.actionId, this.context)?.getSnapshot() ?? null
            const runActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
            const refreshedSelection = this.snapshot.selectedConversation
                ? conversations.find(({ path }) => path === this.snapshot.selectedConversation?.path) ?? this.snapshot.selectedConversation
                : null
            let selectedConversation = runActive
                ? refreshedSelection
                : refreshedSelection ?? latestWaitingConversation(conversations, this.actionId, this.context)
            const initialSelectionPath = this.initialSelectionPath
            this.initialSelectionPath = null
            if (!runActive && !selectedConversation && initialSelectionPath) {
                try {
                    const loadedConversation = await defaultLoadConversation(initialSelectionPath)
                    if (request !== this.loadRequest) return
                    this.validateSelection(loadedConversation)
                    selectedConversation = loadedConversation
                } catch (error) {
                    if (request !== this.loadRequest) return

                    this.setSnapshot({ conversations, loading: false, selectedConversation: null })
                    dialogService.error(error, { fallbackMessage: 'Could not load agent conversation' })
                    return
                }
            }
            this.setSnapshot({ conversations, loading: false, selectedConversation })
            if (selectedConversation) actionPromptDraftService.clearDraft(this.actionId, this.context, null)
        } catch (error) {
            if (request !== this.loadRequest) return

            this.setSnapshot({ conversations: [], loading: false, selectedConversation: null })
            dialogService.error(error, { fallbackMessage: 'Could not load agent conversations' })
        }
    }

    async select(path: string) {
        const request = this.loadRequest + 1
        this.loadRequest = request
        if (!path) {
            this.setSnapshot({ ...this.snapshot, selectedConversation: null })
            this.clearPromptDraft()
            return
        }

        try {
            const conversation = await defaultLoadConversation(path)
            if (request !== this.loadRequest) return
            this.validateSelection(conversation)

            this.setSnapshot({ ...this.snapshot, selectedConversation: conversation })
            this.clearPromptDraft()
        } catch (error) {
            if (request === this.loadRequest) {
                dialogService.error(error, { fallbackMessage: 'Could not load agent conversation' })
            }
        }
    }

    conversationOptions(liveConversation: AgentConversation | null): AgentConversation[]
    conversationOptions(liveConversation: ConversationPickerConversation | null): ConversationPickerConversation[]
    conversationOptions(liveConversation: ConversationPickerConversation | null) {
        const selected = this.snapshot.selectedConversation
        const conversations = selected ? [...this.snapshot.conversations, selected] : this.snapshot.conversations

        return conversationOptions(conversations, this.actionId, this.context, liveConversation)
    }

    continuationPath(liveConversation: AgentConversation | null) {
        return liveConversation?.path ?? this.snapshot.selectedConversation?.path ?? null
    }

    /** Applies one backend-returned conversation without another persistence round trip. */
    updateConversation(conversation: AgentConversation) {
        this.validateSelection(conversation)
        const conversations = this.snapshot.conversations.some(({ path }) => path === conversation.path)
            ? this.snapshot.conversations.map((current) => (current.path === conversation.path ? conversation : current))
            : [...this.snapshot.conversations, conversation]
        const selectedConversation = this.snapshot.selectedConversation?.path === conversation.path
            ? conversation
            : this.snapshot.selectedConversation
        this.setSnapshot({ ...this.snapshot, conversations, selectedConversation })
    }

    private clearPromptDraft() {
        const run = actionRunRegistry.getActionRunStore(this.actionId, this.context)?.getSnapshot() ?? null
        actionPromptDraftService.clearDraft(this.actionId, this.context, run)
    }

    private validateSelection(conversation: AgentConversation) {
        if (!belongsToContext(conversation, this.context)) throw new Error('Selected agent conversation belongs to another context')
        if (conversation.actionId !== this.actionId) throw new Error('Selected agent conversation belongs to another action')
    }

    private setSnapshot(snapshot: ActionConversationSnapshot) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

import { useEffect, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { cardPopupService, subscribeCardPopups } from '../../../services/card_popup_service'
import { agentAcknowledgementService } from '../../../services/agents/agent_acknowledgement_service'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import { ActionConversationChat } from './action_conversation_chat'
import type { ActionConversationStore } from './action_conversation_store'

interface ActionConversationChatOwnerProps {
    actionId: string
    context: ActionContext
    popupEntryId?: string
    store: ActionConversationStore
}

/** Subscribes chat boundary to selected conversation, scoped acknowledgement, and popup stacking. */
export function ActionConversationChatOwner(props: ActionConversationChatOwnerProps) {
    const { actionId, context, popupEntryId, store } = props
    const liveConversation = useActionRunSelector(actionId, context, (run) => run?.conversation ?? null)
    const runStatus = useActionRunSelector(actionId, context, (run) => run?.status ?? 'idle')
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const popupEntries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const cardInternalId = context.cardInternalId
    const conversation = liveConversation ?? selectedConversation
    const status = runStatus === 'idle' && conversation?.status === 'waitingForInput' ? 'waitingForInput' : runStatus
    const visible = !!popupEntryId && popupEntries.at(-1)?.id === popupEntryId && !!cardInternalId && !!conversation

    useEffect(() => {
        if (!popupEntryId || !cardInternalId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, cardInternalId, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId,
            cardInternalId,
            actionId,
            conversation,
            false,
        )
    }, [actionId, cardInternalId, conversation, popupEntryId, visible])

    return <ActionConversationChat conversation={conversation} status={status} />
}

import { Typography } from '@mui/material'
import { useEffect, useRef, useState } from 'react'
import type { PopupRunStatus } from '../run/popup/action_popup_defaults'
import { formatDuration } from './conversation_duration'

interface ConversationTimerProps {
    completedAt: string | null
    startedAt: string
    status: PopupRunStatus
}

function elapsedMs(startedAt: string, completedAt: string | null) {
    const end = completedAt ? Date.parse(completedAt) : Date.now()

    return end - Date.parse(startedAt)
}

/**
 * Isolated run timer. While the run is active it ticks once a second; keeping it
 * in its own component means only this node re-renders, not the whole chat log.
 */
export function ConversationTimer({ completedAt, startedAt, status }: ConversationTimerProps) {
    const [elapsed, setElapsed] = useState(() => elapsedMs(startedAt, null))
    const lastTickAtRef = useRef(0)

    useEffect(() => {
        if (completedAt || status !== 'running') return

        lastTickAtRef.current = Date.now()
        const interval = setInterval(() => {
            const now = Date.now()
            const elapsedSinceLastTick = now - lastTickAtRef.current
            lastTickAtRef.current = now
            setElapsed((currentElapsed) => currentElapsed + elapsedSinceLastTick)
        }, 1000)

        return () => clearInterval(interval)
    }, [completedAt, status])

    const displayedElapsed = completedAt ? elapsedMs(startedAt, completedAt) : elapsed

    return (
        <Typography aria-label="Elapsed time" color="text.secondary" variant="caption">
            {`⏱ ${formatDuration(displayedElapsed)}`}
        </Typography>
    )
}

