const {
    accumulateUsage,
    createProviderEventEntry,
    createEventEntry,
    updateProviderSession,
} = require('./agent_conversation');
const { emitRunEvent, hasPendingInteraction } = require('./agent_run_state');
const {
    appendAssistantOutput,
    appendDiagnosticContent,
    completeAssistantOutput,
    lastMessageEntry,
    nextRunSequence,
    replaceAssistantOutput,
    startAssistantItem,
} = require('./agent_run_transcript');
const { redactConversationEvent, redactSecrets } = require('./agent_secret_redaction');
const { requireString } = require('./agent_run_validation');

function handleSessionStarted(service, run, event) {
    run.providerConversationId = event.conversationId;
}

function handleTurnStarted(service, run) {
    run.assistantItemIndex = 0;
    run.assistantItems.clear();
    run.currentAssistantMessageId = null;
    run.liveTurnUsage = null;
    run.turnStarted = true;
}

function handleUsage(service, run, event) {
    run.liveTurnUsage = event.usage;
    const usage = accumulateUsage(run.conversation.usage, event.usage);
    emitRunEvent(run, {
        ...(event.contextWindowUsage !== undefined ? { contextWindowUsage: event.contextWindowUsage } : {}),
        type: 'usage',
        usage,
    });
}

function handleAssistantStarted(service, run, event, timestamp) {
    const item = startAssistantItem(run, requireString(event.itemId, 'assistant item id'), timestamp);
    emitRunEvent(run, { content: '', messageId: item.messageId, sequence: item.sequence, type: 'output' });
}

function handleAssistant(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = run.agent === 'codex'
        ? requireString(event.itemId, 'assistant item id')
        : event.itemId;
    const { message, segment } = appendAssistantOutput(run, safeContent, timestamp, itemId);
    if (segment.length > 0) {
        emitRunEvent(run, { content: segment, messageId: message.id, sequence: message.sequence, type: 'output' });
    }
}

function handleAssistantCompleted(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    const itemId = requireString(event.itemId, 'assistant item id');
    const { message, previousContent, replaced } = replaceAssistantOutput(run, safeContent, timestamp, itemId);
    if (!replaced) return;

    emitRunEvent(run, {
        content: safeContent,
        messageId: message.id,
        previousContent,
        replace: true,
        sequence: message.sequence,
        type: 'output',
    });
}

function handleChangedPaths(service, run, event) {
    event.paths.forEach((filePath) => run.changedPaths.add(filePath));
}

/** Provider events are keyed by `providerItemId` so a later revision of the same item replaces its entry. */
function handleEvent(service, run, event, timestamp) {
    const safeEvent = redactConversationEvent(event.event, run.secretValues);
    const providerItemId = requireString(safeEvent.providerItemId, 'event providerItemId');
    const currentIndex = run.providerEventEntryIndexes.get(providerItemId);
    let eventEntry;
    if (currentIndex !== undefined) {
        const current = run.conversation.entries[currentIndex];
        eventEntry = createProviderEventEntry(safeEvent, current.id, timestamp, current.sequence);
        run.conversation.entries[currentIndex] = eventEntry;
    } else {
        const previousEntry = run.conversation.entries.at(-1);
        if (safeEvent.type === 'diagnostic' && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            eventEntry = appendDiagnosticContent(previousEntry, safeEvent.content);
            run.conversation.entries[run.conversation.entries.length - 1] = eventEntry;
        } else {
            const sequence = nextRunSequence(run);
            eventEntry = createProviderEventEntry(
                safeEvent,
                `${run.id}-event-${sequence}`,
                timestamp,
                sequence,
            );
            run.providerEventEntryIndexes.set(providerItemId, run.conversation.entries.length);
            run.conversation.entries.push(eventEntry);
        }
    }
    emitRunEvent(run, { event: eventEntry, type: 'agentEvent' });
}

function handleTranscript(service, run, event, timestamp) {
    const safeContent = redactSecrets(event.content, run.secretValues);
    run.conversation.entries.push(createEventEntry(
        `${run.id}-provider-${run.conversation.entries.length}`,
        event.toolType,
        safeContent,
        timestamp,
        nextRunSequence(run),
    ));
}

function handleError(service, run, event) {
    service.recordOutput(run.id, 'stderr', event.content);
}

function handleFatal(service, run, event) {
    service.failStreamingRun(run, new Error(event.content));
}

function handleSessionFailed(service, run, event) {
    run.missingSession = event.missingSession;
    service.failStreamingRun(run, new Error(event.content));
}

async function handleQuestion(service, run, event) {
    run.conversation.status = 'waitingForInput';
    run.waitingForQuestion = true;
    run.pendingQuestions = event.questions;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { questions: event.questions, requestId: event.requestId, state: 'waitingForInput', type: 'question' });
}

async function handleApproval(service, run, event) {
    const requestId = event.approval.requestId;
    if (run.pendingApprovals.has(requestId)) throw new Error(`Duplicate agent approval request id: ${requestId}`);
    run.pendingApprovals.set(requestId, { ...event.approval, submitted: false });
    run.conversation.status = 'waitingForInput';
    await service.persistCheckpoint(run);
    emitRunEvent(run, { approval: event.approval, state: 'waitingForInput', type: 'approval' });
}

function handleApprovalSubmitted(service, run, event) {
    const approval = run.pendingApprovals.get(event.requestId);
    if (!approval) return;
    approval.submitted = true;
    emitRunEvent(run, { requestId: event.requestId, type: 'approvalSubmitted' });
}

function handleApprovalResolved(service, run, event) {
    if (!run.pendingApprovals.delete(event.requestId)) return;
    const state = hasPendingInteraction(run) ? 'waitingForInput' : 'running';
    run.conversation.status = state;
    emitRunEvent(run, { requestId: event.requestId, state, type: 'approvalResolved' });
    emitRunEvent(run, { state, type: 'state' });
}

/**
 * End of a streaming turn: settle the assistant message, then either shut the process down,
 * send the message queued while the turn was running, or park the run waiting for input.
 */
async function handleTurnCompleted(service, run, event, timestamp) {
    completeAssistantOutput(run, timestamp);
    run.turnActive = false;
    run.waitingForQuestion = false;
    run.pendingApprovals.clear();
    run.missingSession = run.missingSession || event.missingSession;
    if (event.missingSession) run.finishing = true;
    if (event.usage) {
        run.liveTurnUsage = event.usage;
        run.conversation.usage = accumulateUsage(run.conversation.usage, run.liveTurnUsage);
        run.liveTurnUsage = null;
    }
    if (event.contextWindowUsage !== undefined) {
        if (event.contextWindowUsage) run.conversation.contextWindowUsage = event.contextWindowUsage;
        else delete run.conversation.contextWindowUsage;
    }
    if (event.usage || event.contextWindowUsage !== undefined) {
        emitRunEvent(run, {
            ...(event.contextWindowUsage !== undefined ? { contextWindowUsage: event.contextWindowUsage } : {}),
            type: 'usage',
            usage: run.conversation.usage,
        });
    }
    if (event.error) {
        service.failStreamingRun(run, new Error(event.error));
        return;
    }
    if (run.finishing) {
        service.beginFinishShutdown(run);
        return;
    }
    if (run.queuedMessage) {
        const { content, revision } = run.queuedMessage;
        run.conversation.status = 'waitingForInput';
        await service.sendStreamingMessage(run, content);
        run.queuedMessage = null;
        run.sentQueuedMessageRevision = revision;
        return;
    }
    const synchronizedMessage = lastMessageEntry(run.conversation);
    if (synchronizedMessage) updateProviderSession(run, synchronizedMessage.id, timestamp);
    run.conversation.status = 'waitingForInput';
    run.conversation.completedAt = null;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
}

/** Keyed by streaming event type; unknown types are ignored. Each handler takes `(service, run, event, timestamp)`. */
const STREAMING_EVENT_HANDLERS = {
    approval: handleApproval,
    approvalResolved: handleApprovalResolved,
    approvalSubmitted: handleApprovalSubmitted,
    assistant: handleAssistant,
    assistantCompleted: handleAssistantCompleted,
    assistantStarted: handleAssistantStarted,
    changedPaths: handleChangedPaths,
    error: handleError,
    event: handleEvent,
    fatal: handleFatal,
    question: handleQuestion,
    sessionFailed: handleSessionFailed,
    sessionStarted: handleSessionStarted,
    transcript: handleTranscript,
    turnCompleted: handleTurnCompleted,
    turnStarted: handleTurnStarted,
    usage: handleUsage,
};

module.exports = { STREAMING_EVENT_HANDLERS };

const { sumAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');

function createMessageEntry(id, role, content, timestamp, agent, sequence) {
    return {
        ...(agent ? { agent } : {}),
        content,
        id,
        kind: 'message',
        role,
        ...(Number.isSafeInteger(sequence) ? { sequence } : {}),
        timestamp,
    };
}

function createEventEntry(id, type, content, timestamp, sequence) {
    return {
        content,
        id,
        kind: 'event',
        ...(Number.isSafeInteger(sequence) ? { sequence } : {}),
        timestamp,
        type,
    };
}

function createProviderEventEntry(providerEvent, id, timestamp, sequence) {
    const event = {
        content: providerEvent.content,
        id,
        kind: 'event',
        label: providerEvent.label,
        providerItemId: providerEvent.providerItemId,
        sequence,
        status: providerEvent.status,
        timestamp,
        type: providerEvent.type,
    };
    if (typeof providerEvent.command === 'string') event.command = providerEvent.command;
    if (Number.isSafeInteger(providerEvent.deletions) && providerEvent.deletions >= 0) event.deletions = providerEvent.deletions;
    if (Array.isArray(providerEvent.details)) event.details = [...providerEvent.details];
    if (Number.isFinite(providerEvent.durationMs)) event.durationMs = providerEvent.durationMs;
    if (Number.isSafeInteger(providerEvent.exitCode)) event.exitCode = providerEvent.exitCode;
    if (Number.isSafeInteger(providerEvent.insertions) && providerEvent.insertions >= 0) event.insertions = providerEvent.insertions;
    if (typeof providerEvent.output === 'string') event.output = providerEvent.output;
    if (Array.isArray(providerEvent.summary)) event.summary = [...providerEvent.summary];
    if (typeof providerEvent.workingDirectory === 'string') event.workingDirectory = providerEvent.workingDirectory;

    return event;
}

function accumulateUsage(current, turn) {
    return sumAgentTokenUsage([current, turn]);
}

function createConversation(request, id, startedAt, reference) {
    if (request.conversation) {
        return {
            ...request.conversation,
            completedAt: null,
            entries: [...request.conversation.entries],
            path: reference,
            providerSessions: [...request.conversation.providerSessions],
            status: 'running',
        };
    }

    return {
        actionId: request.actionId ?? null,
        cardInternalId: request.activityOrigin.kind === 'card' ? request.activityOrigin.cardInternalId : null,
        cardPath: request.cardPath ?? null,
        completedAt: null,
        entries: [],
        hasExplicitTitle: true,
        id,
        path: reference,
        providerSessions: [],
        startedAt,
        status: 'running',
        title: typeof request.title === 'string' && request.title.length > 0 ? request.title : 'Agent run',
        viewed: true,
    };
}

/** Snapshots the mutable conversation collections while reusing immutable entries. */
function snapshotConversation(conversation) {
    return {
        ...conversation,
        entries: [...conversation.entries],
        providerSessions: [...conversation.providerSessions],
    };
}

function updateProviderSession(run, synchronizedThroughMessageId, completedAt) {
    const conversationId = run.providerConversationId ?? run.request.providerConversationId;
    if (!conversationId) return;

    const sessions = run.conversation.providerSessions;
    const current = sessions.find(({ agent }) => agent === run.agent);
    const nextSession = {
        agent: run.agent,
        conversationId,
        createdAt: current?.createdAt ?? completedAt,
        lastUsedAt: completedAt,
        synchronizedThroughMessageId,
    };
    run.conversation.providerSessions = current
        ? sessions.map((session) => (session.agent === run.agent ? nextSession : session))
        : [...sessions, nextSession];
}

module.exports = {
    accumulateUsage,
    createProviderEventEntry,
    createConversation,
    createEventEntry,
    createMessageEntry,
    snapshotConversation,
    updateProviderSession,
};

import type { AgentConversation } from '../app/src/data/data_types.ts'

/** Parse one canonical conversation record while discarding malformed optional entries. */
export function parseAgentConversation(content: string, referencePath: string): AgentConversation

import { normalizeAgentTokenUsage } from './agent_usage_math.mjs'

const AGENT_MESSAGE_ROLES = new Set(['assistant', 'user'])
const AGENT_STATUSES = new Set(['cancelled', 'completed', 'failed', 'running', 'waitingForInput'])
const INTERNAL_EVENT_TYPES = new Set(['closed', 'started', 'turnCompleted'])

function requiredString(value, fieldName) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Malformed agent conversation: missing ${fieldName}`)

    return value
}

function optionalString(value) {
    return typeof value === 'string' && value.length > 0 ? value : null
}

function optionalInteger(value) {
    return Number.isSafeInteger(value) ? value : null
}

function optionalNonNegativeInteger(value) {
    return Number.isSafeInteger(value) && value >= 0 ? value : null
}

function optionalNumber(value) {
    return typeof value === 'number' && Number.isFinite(value) ? value : null
}

function optionalStringArray(value) {
    return Array.isArray(value) && value.every((entry) => typeof entry === 'string') ? [...value] : null
}

function normalizeMessage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    if (!AGENT_MESSAGE_ROLES.has(value.role)) return null
    if (typeof value.content !== 'string') return null
    const id = optionalString(value.id)
    const timestamp = optionalString(value.timestamp)
    if (!id || !timestamp) return null
    const agent = optionalString(value.agent)
    const sequence = optionalInteger(value.sequence)

    return {
        ...(agent ? { agent } : {}),
        content: value.content,
        id,
        kind: 'message',
        role: value.role,
        ...(sequence !== null ? { sequence } : {}),
        timestamp,
    }
}

function normalizeEvent(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    if (typeof value.content !== 'string') return null
    const id = optionalString(value.id)
    const timestamp = optionalString(value.timestamp)
    const type = optionalString(value.type)
    if (!id || !timestamp || !type) return null
    const command = optionalString(value.command)
    const deletions = optionalNonNegativeInteger(value.deletions)
    const details = optionalStringArray(value.details)
    const durationMs = optionalNumber(value.durationMs)
    const exitCode = optionalInteger(value.exitCode)
    const insertions = optionalNonNegativeInteger(value.insertions)
    const label = optionalString(value.label)
    const output = value.type !== 'commandExecution' && typeof value.output === 'string' ? value.output : null
    const providerItemId = optionalString(value.providerItemId)
    const sequence = optionalInteger(value.sequence)
    const status = optionalString(value.status)
    const summary = optionalStringArray(value.summary)
    const workingDirectory = optionalString(value.workingDirectory)

    return {
        ...(command ? { command } : {}),
        content: value.content,
        ...(deletions !== null ? { deletions } : {}),
        ...(details ? { details } : {}),
        ...(durationMs !== null ? { durationMs } : {}),
        ...(exitCode !== null ? { exitCode } : {}),
        id,
        ...(insertions !== null ? { insertions } : {}),
        kind: 'event',
        ...(label ? { label } : {}),
        ...(output !== null ? { output } : {}),
        ...(providerItemId ? { providerItemId } : {}),
        ...(sequence !== null ? { sequence } : {}),
        ...(status ? { status } : {}),
        ...(summary ? { summary } : {}),
        timestamp,
        type,
        ...(workingDirectory ? { workingDirectory } : {}),
    }
}

function normalizeProviderSession(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    const agent = optionalString(value.agent)
    const conversationId = optionalString(value.conversationId)
    const createdAt = optionalString(value.createdAt)
    const lastUsedAt = optionalString(value.lastUsedAt)
    const synchronizedThroughMessageId = optionalString(value.synchronizedThroughMessageId)
    if (!agent || !conversationId || !createdAt || !lastUsedAt || !synchronizedThroughMessageId) return null

    return { agent, conversationId, createdAt, lastUsedAt, synchronizedThroughMessageId }
}

function normalizeContextWindowUsage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    const { capacityTokens, usedTokens } = value
    if (!Number.isSafeInteger(usedTokens) || usedTokens < 0) return null
    if (!Number.isSafeInteger(capacityTokens) || capacityTokens <= 0) return null

    return { capacityTokens, usedTokens }
}

function normalizeArray(value, normalize) {
    if (!Array.isArray(value)) return []

    return value.map(normalize).filter((entry) => entry !== null)
}

function coalesceDiagnosticEntries(entries) {
    const groupedEntries = []
    for (const entry of entries) {
        const previousEntry = groupedEntries.at(-1)
        if (entry.kind === 'event' && entry.type === 'diagnostic'
            && previousEntry?.kind === 'event' && previousEntry.type === 'diagnostic') {
            groupedEntries[groupedEntries.length - 1] = {
                ...previousEntry,
                content: `${previousEntry.content}\n${entry.content}`,
            }
            continue
        }
        groupedEntries.push(entry)
    }

    return groupedEntries
}

function isConversationEntry(entry) {
    if (entry.kind !== 'event') return true
    if (INTERNAL_EVENT_TYPES.has(entry.type)) return false

    return entry.type !== 'error' || typeof entry.providerItemId === 'string'
}

function normalizeEntries(value) {
    if (!Array.isArray(value)) throw new Error('Malformed agent conversation: missing entries')

    const entries = value.map((entry, index) => {
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
            throw new Error(`Malformed agent conversation: invalid entries[${index}]`)
        }
        const normalized = entry.kind === 'message'
            ? normalizeMessage(entry)
            : entry.kind === 'event'
                ? normalizeEvent(entry)
                : null
        if (!normalized) throw new Error(`Malformed agent conversation: invalid entries[${index}]`)

        return normalized
    })

    return coalesceDiagnosticEntries(entries.filter(isConversationEntry))
}

/** Parse one canonical conversation record and validate every ordered entry. */
export function parseAgentConversation(content, referencePath) {
    const parsed = JSON.parse(content)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Malformed agent conversation: root must be an object')
    const id = requiredString(parsed.id, 'id')
    const status = requiredString(parsed.status, 'status')
    if (!AGENT_STATUSES.has(status)) throw new Error(`Malformed agent conversation: invalid status ${status}`)
    const startedAt = requiredString(parsed.startedAt, 'startedAt')
    const hasExplicitTitle = typeof parsed.title === 'string' && parsed.title.trim().length > 0
    const contextWindowUsage = normalizeContextWindowUsage(parsed.contextWindowUsage)
    const usage = normalizeAgentTokenUsage(parsed.usage)
    if (parsed.viewed !== undefined && typeof parsed.viewed !== 'boolean') {
        throw new Error('Malformed agent conversation: invalid viewed')
    }

    return {
        actionId: optionalString(parsed.actionId),
        cardInternalId: optionalString(parsed.cardInternalId),
        cardPath: optionalString(parsed.cardPath),
        completedAt: optionalString(parsed.completedAt),
        ...(contextWindowUsage ? { contextWindowUsage } : {}),
        entries: normalizeEntries(parsed.entries),
        hasExplicitTitle,
        id,
        path: referencePath,
        providerSessions: normalizeArray(parsed.providerSessions, normalizeProviderSession),
        startedAt,
        status,
        title: hasExplicitTitle ? parsed.title : id,
        ...(usage ? { usage } : {}),
        viewed: parsed.viewed ?? true,
    }
}

const { JsonLineBuffer } = require('./agent_event_utils');
const { createAgentProviderProtocolParser } = require('./agent_provider_protocol');
const { createAgentStreamingAdapter } = require('./agent_streaming_adapter');
const { createProviderEventEntryIndexes } = require('./agent_run_transcript');

function emitRunEvent(run, event) {
    if (!run.onEvent) return;

    run.onEvent({ ...event, runId: run.id });
}

function hasPendingInteraction(run) {
    return run.waitingForQuestion || run.pendingApprovals.size > 0;
}

function writeJsonLine(stream, message) {
    return new Promise((resolve, reject) => {
        stream.write(`${JSON.stringify(message)}\n`, (error) => {
            if (error) {
                reject(error);
                return;
            }

            resolve();
        });
    });
}

/**
 * The mutable state for one agent turn. `AgentRunnerService` keeps these in `processes` keyed by run id,
 * and `persistCheckpoint` spreads the whole object into the persistence layer, so the field set is a contract.
 */
function createRun({
    agent,
    child,
    conversation,
    environment,
    executable,
    id,
    nextSequence,
    onComplete,
    onCompletionError,
    onEvent,
    reference,
    request,
    startedAt,
    streaming,
}) {
    const { promise: closed, resolve: resolveClosed } = Promise.withResolvers();

    return {
        providerEventEntryIndexes: createProviderEventEntryIndexes(conversation.entries),
        agent,
        assistantItemIndex: 0,
        assistantItems: new Map(),
        cancelled: false,
        child,
        changedPaths: new Set(),
        closed,
        conversation,
        codexCacheErrorReported: false,
        currentAssistantMessageId: null,
        environment,
        executable,
        finishForced: false,
        finishTimeout: null,
        id,
        missingSession: false,
        nextSequence,
        onComplete,
        onCompletionError,
        onEvent,
        interactionWrites: Promise.resolve(),
        liveTurnUsage: null,
        pendingQuestions: [],
        pendingApprovals: new Map(),
        persistence: Promise.resolve(),
        providerConversationId: null,
        protocolLines: null,
        protocolHandling: Promise.resolve(),
        reference,
        reportedProviderErrors: new Set(),
        resolveClosed,
        queuedMessage: null,
        queuedMessageRevision: -1,
        sentQueuedMessageRevision: -1,
        queuedMessageSessionId: 0,
        secretValues: new Set(),
        request,
        stderr: '',
        stderrBuffer: '',
        stderrHandling: Promise.resolve(),
        finishing: false,
        stdout: '',
        startedAt,
        streaming,
        streamingFailure: null,
        turnStarted: false,
        turnIndex: 1,
        turnActive: streaming,
        termination: null,
        suspended: false,
        turnUsage: null,
        waitingForQuestion: false,
    };
}

/**
 * Wires the run to its provider protocol: streaming runs get the adapter plus a JSONL line buffer,
 * batch runs get the one-shot protocol parser.
 */
function attachRunProtocol(run, {
    onCodexRuntimeEvent,
    onMalformedOutput,
    onProviderEvent,
    onStreamingEvent,
    onStreamingLine,
    providerConversationId,
    rootPath,
}) {
    const writeLine = (message) => writeJsonLine(run.child.stdin, message);
    run.streamingAdapter = run.streaming
        ? createAgentStreamingAdapter(
            run.agent,
            writeLine,
            onStreamingEvent,
            rootPath,
            providerConversationId,
            onCodexRuntimeEvent,
        )
        : null;
    run.protocolLines = run.streaming ? new JsonLineBuffer(run.id, onStreamingLine) : null;
    run.parser = run.streaming
        ? null
        : createAgentProviderProtocolParser(run.agent, onProviderEvent, onMalformedOutput, rootPath);

    return run;
}

function createRunResult(request, exitCode, run) {
    return {
        command: request.command,
        conversation: run.conversation,
        exitCode,
        missingSession: run.missingSession,
        prompt: request.prompt,
        reference: run.reference,
        runId: run.id,
        stderr: run.stderr,
        stdout: run.stdout,
        changedPaths: [...run.changedPaths],
        turnStarted: run.turnStarted,
    };
}

module.exports = {
    attachRunProtocol,
    createRun,
    createRunResult,
    emitRunEvent,
    hasPendingInteraction,
    writeJsonLine,
};

